bool mrhiFeaturesWithin(const mrhiFeatures* asked, const mrhiFeatures* granted)
{
    return true
        && (!asked->timestampQuery || granted->timestampQuery)
        && (!asked->pipelineStatisticsQuery || granted->pipelineStatisticsQuery)
        && (!asked->textureCompressionBc || granted->textureCompressionBc)
        && (!asked->textureCompressionEtc2 || granted->textureCompressionEtc2)
        && (!asked->textureCompressionAstc || granted->textureCompressionAstc)
        && (!asked->float32Filterable || granted->float32Filterable)
        && (!asked->rg11b10Renderable || granted->rg11b10Renderable)
        && (!asked->dualSourceBlending || granted->dualSourceBlending)
        && (!asked->unclippedDepth || granted->unclippedDepth)
        && (!asked->shaderF16 || granted->shaderF16)
        && (!asked->subgroups || granted->subgroups)
        && (!asked->shaderInt64 || granted->shaderInt64)
        && (!asked->indirectFirstInstance || granted->indirectFirstInstance)
        && (!asked->multiDrawIndirectCount || granted->multiDrawIndirectCount)
        && (!asked->multiview || granted->multiview)
        && (!asked->bindlessSampling || granted->bindlessSampling)
        && (!asked->bindlessHeterogeneous || granted->bindlessHeterogeneous)
        && (!asked->presentTiming || granted->presentTiming);
}

bool mrhiLimitsWithin(const mrhiLimits* asked, const mrhiLimits* granted)
{
    return true
        && asked->textureDimension2d <= granted->textureDimension2d
        && asked->textureDimension3d <= granted->textureDimension3d
        && asked->textureArrayLayers <= granted->textureArrayLayers
        && asked->bindingTables <= granted->bindingTables
        && asked->bindingsPerTable <= granted->bindingsPerTable
        && asked->sampledTexturesPerStage <= granted->sampledTexturesPerStage
        && asked->samplersPerStage <= granted->samplersPerStage
        && asked->storageBuffersPerStage <= granted->storageBuffersPerStage
        && asked->storageTexturesPerStage <= granted->storageTexturesPerStage
        && asked->uniformBuffersPerStage <= granted->uniformBuffersPerStage
        && asked->uniformBindingBytes <= granted->uniformBindingBytes
        && asked->storageBindingBytes <= granted->storageBindingBytes
        && asked->uniformOffsetAlignment >= granted->uniformOffsetAlignment
        && asked->storageOffsetAlignment >= granted->storageOffsetAlignment
        && asked->vertexBuffers <= granted->vertexBuffers
        && asked->tablesPlusVertexBuffers <= granted->tablesPlusVertexBuffers
        && asked->bufferBytes <= granted->bufferBytes
        && asked->vertexAttributes <= granted->vertexAttributes
        && asked->vertexStride <= granted->vertexStride
        && asked->interStageVariables <= granted->interStageVariables
        && asked->colorAttachments <= granted->colorAttachments
        && asked->colorBytesPerSample <= granted->colorBytesPerSample
        && asked->workgroupStorageBytes <= granted->workgroupStorageBytes
        && asked->workgroupInvocations <= granted->workgroupInvocations
        && asked->workgroupSizeX <= granted->workgroupSizeX
        && asked->workgroupSizeY <= granted->workgroupSizeY
        && asked->workgroupSizeZ <= granted->workgroupSizeZ
        && asked->workgroupsPerDimension <= granted->workgroupsPerDimension
        && asked->rootBlockBytes <= granted->rootBlockBytes
        && asked->heapSize <= granted->heapSize
        && asked->samplerHeapSize <= granted->samplerHeapSize
        && asked->framesInFlight <= granted->framesInFlight;
}

void mrhiMaskFeatures(mrhiFeatures* features, mrhiDriverKind driver)
{
    switch (driver)
    {
    case mrhi_driverVulkan:
        break;
    case mrhi_driverD3d12:
        features->textureCompressionEtc2 = false;
        features->textureCompressionAstc = false;
        break;
    case mrhi_driverMetal:
        break;
    case mrhi_driverWebGpu:
        features->pipelineStatisticsQuery = false;
        features->shaderInt64 = false;
        features->multiDrawIndirectCount = false;
        features->multiview = false;
        features->bindlessSampling = false;
        features->bindlessHeterogeneous = false;
        features->presentTiming = false;
        break;
    default:
        break;
    }
}

